    step1Desc: "కంట్రోల్ బార్‌లో మీ ప్రారంభ తేదీని ఎంచుకోవడం ద్వారా ప్రారంభించండి. సముద్ర రంగాలలో స్థిరమైన అంచనా మరియు విశ్వసనీయ వైరుధ్య గుర్తింపును నిర్ధారించడానికి సిస్టమ్ స్వయంచాలకంగా బలమైన 4-రోజుల స్పాటియోటెమ్టోరల్ విశ్లేషణ విండోను గణిస్తుంది మరియు సింక్రొనైజ్ చేస్తుంది.",
