    step1Desc: "கண்ட்ரோல் பாரில் தொடக்கத் தேதியைத் தேர்ந்தெடுப்பதன் மூலம் தொடங்கவும். கடல்சார் துறைகளில் நிலையான முன்னறிவிப்பு மற்றும் நம்பகமான முரண்பாடு கண்டறிதலை உறுதி செய்வதற்காக அமைப்பு தானாகவே ஒரு வலுவான 4-நாள் இட-கால பகுப்பாய்வு சாளரத்தைக் கணக்கிட்டு ஒத்திசைக்கிறது.",
    step2Title: "2. புள்ளி அடிப்படையிலான கடல்சார் விவரக்குறிப்பு",
    step2Desc: "ஊடாடும் வரைபடத்தில் எங்கு வேண்டுமானாலும் கிளிக் செய்யவும் அல்லது துல்லியமான அகலாத்து மற்றும் தீர்க்கரேகை ஆயங்களை கைமுறையாக உள்ளிடவும். உயர்-தெளிவுத்திறன் கடற்கரை முகமூடிகளுக்கு எதிராக ஆயங்கள் தானாகவே சரிபார்க்கப்பட்டு, அருகிலுள்ள பாதுகாப்பான பெருங்கடல் கிரிட் புள்ளிக்குத் திருத்தப்படுகின்றன.",
    step3Title: "3. மேற்பரப்பு & ஆழத்தின் அளவுருக்களைப் பகுப்பாய்வு செய்யவும்",
    step3Desc: "டைனமிக் பக்கவாட்டு குழு நிகழ்நேர மேற்பரப்பு அளவுருக்களைக் காட்டுகிறது, இதில் கடல் மேற்பரப்பு வெப்பநிலை (SST), கடல் மேற்பரப்பு உப்புத்தன்மை (SSS), கடல் மேற்பரப்பு உயரம் (SSH), மற்றும் கிழக்கு/வடக்கு நீரோட்ட திசைவேகங்கள் (UO, VO) ஆகியவை அடங்கும், அதனுடன் ஊடாடும் ஆழம்-சார்ந்த செங்குத்து வெப்பநிலை சுயவிவர வரைபடமும் உள்ளது.",
    step4Title: "4. பிராந்திய அடுக்கு முறைகள் மற்றும் காட்சிப்படுத்தல்",
    step4Desc: "ஆய புலங்களை காலியாக விட்டுவிட்டு குறிப்பிட்ட ஆழ மதிப்பைத் தேர்ந்தெடுக்கவும், இதன் மூலம் விரிவான பிராந்திய காட்சிப்படுத்தல் முறைகள் திறக்கப்படுகின்றன: சுயாதீன ARGO கண்காணிப்பு கிரவுண்ட் ட்ரூத் வரைபடங்கள், கன்வ்பார்மர் கணிப்புகள் மற்றும் முழுமையான பிராந்திய பிழை மேப்பிங்.",
