    step1Desc: "કંટ્રોલ બારમાં તમારી પ્રારંભ તારીખ પસંદ કરીને શરૂ કરો. સિસ્ટમ દરિયાઈ ક્ષેત્રોમાં સતત આગાહી અને વિશ્વસનીય વિસંગતતા શોધવાનું સુનિશ્ચિત કરવા માટે આપમેળે એક મજબૂત 4-દિવસીય સ્પાટીઓટેમ્પોરલ વિશ્લેષણ વિન્ડોની ગણતરી અને સિંક્રનાઇઝ કરે છે.",
    step2Title: "2. બિંદુ-આધારિત દરિયાઈ પ્રોફાઇલિંગ",
    step2Desc: "ઇન્ટરેક્ટિવ નકશા પર ગમે ત્યાં ક્લિક કરો અથવા ચોક્કસ અક્ષાંશ અને રેખાંશ સંકલનો જાતે ઇનપુટ કરો. ઉચ્ચ-રિઝોલ્યુશન કોસ્ટલાઇન માસ્ક સામે જમીન સંકલનો આપમેળે ચકાસાય છે અને નજીકના સલામત મહાસાગર ગ્રીડ પોઇન્ટ પર રીડાયરેક્ટ થાય છે.",
    step3Title: "3. સપાટી અને ઊંડાઈના પરિમાણોનું વિશ્લેષણ કરો",
    step3Desc: "ડાયનેમિક સાઇડ પેનલ વાસ્તવિક સમયના સપાટી પરિમાણો પ્રદર્શિત કરે છે જેમાં સી સરફેસ ટેમ્પરેચર (SST), સી સરફેસ સેલિનિટી (SSS), સી સરફેસ હાઇટ (SSH), અને પૂર્વ તરફી/ઉત્તર તરફી પ્રવાહ વેગ (UO, VO) સામેલ છે, સાથે એક ઇન્ટરેક્ટિવ ઊંડાઈ-વાર વર્ટિકલ ટેમ્પરેચર પ્રોફાઇલ ગ્રાફ છે.",
    step4Title: "4. પ્રાદેશિક સ્તર મોડ્સ અને વિઝ્યુલાઇઝેશન",
    step4Desc: "સંકલન ક્ષેત્રો ખાલી છોડીને એક ચોક્કસ ઊંડાઈ મૂલ્ય પસંદ કરો જેથી વ્યાપક પ્રાદેશિક વિઝ્યુલાઇઝેશન મોડ્સ અનલૉક થાય: સ્વતંત્ર ARGO અવલોકન ગ્રાウンド ટ્રુથ નકશા, કન્વ્ફોર્મર ડીપ-લર્નિંગ આગાહીઓ, અને સંપૂર્ણ અવકાશી ત્રુટિ મેપિંગ.",
