    guidelinesTitle: "വെബ് മാർഗ്ഗനിർദ്ദേശങ്ങളും ഉപയോഗ ഡോക്യുമെന്റേഷനും",
    platformOverview: "പ്ലാറ്റ്‌ഫോം അവലോകനം",
    navigationGuide: "നാവിഗേഷൻ ഗൈഡ്",
    guidelinesSubtitle: "വിപുലമായ സമുദ്ര വിശകലനത്തിനായി സ്പേഷ്യോ ടെംപോറൽ സമുദ്ര താപനില ഇന്റലിജൻസ് പ്ലാറ്റ്‌ഫോം മാസ്റ്റർ ചെയ്യുക",
    stepInstructions: "ഘട്ടം ഘട്ടമായുള്ള പ്രവർത്തന നിർദ്ദേശങ്ങൾ",
    step1Title: "1. തീയതി പരിധിയും വിശകലന വിൻഡോയും തിരഞ്ഞെടുക്കുക",
    step1Desc: "കൺട്രോൾ ബാറിൽ നിങ്ങളുടെ ആരംഭ തീയതി തിരഞ്ഞെടുത്ത് ആരംഭിക്കുക. സമുദ്ര മേഖലകളിൽ സ്ഥിരമായ പ്രവചനവും വിശ്വസനീയമായ ക്രമക്കേട് കണ്ടെത്തലും ഉറപ്പാക്കാൻ സിസ്റ്റം സ്വയമേവ ശക്തമായ 4 ദിവസത്തെ സ്പേഷ്യോ ടെംപോറൽ വിശകലന വിൻഡോ കണക്കാക്കുകയും സിൻക്രോണൈസ് ചെയ്യുകയും ചെയ്യുന്നു.",
    step2Title: "2. പോയിന്റ് അടിസ്ഥാനമാക്കിയുള്ള സമുദ്ര പ്രൊഫൈലിംഗ്",
    step2Desc: "ഇന്ററാക്ടീവ് മാപ്പിൽ എവിടെയെങ്കിലും ക്ലിക്ക് ചെയ്യുക അല്ലെങ്കിൽ കൃത്യമായ അക്ഷാംശവും രേഖാംശ കോർഡിനേറ്റുകളും സ്വയം നൽകുക. ഉയർന്ന റെസല്യൂഷൻ കോസ്റ്റ്‌ലൈൻ മാസ്കുകൾക്കെതിരെ കോർഡിനേറ്റുകൾ സ്വയം പരിശോധിക്കുകയും അടുത്തുള്ള സുരക്ഷിത സമുദ്ര ഗ്രിഡ് പോയിന്റിലേക്ക് റീഡയറക്‌ട് ചെയ്യുകയും ചെയ്യുന്നു.",
    step3Title: "3. ഉപരിതലവും ആഴത്തിലുള്ള പാരാമീറ്ററുകളും വിശകലനം ചെയ്യുക",
    step3Desc: "ഡൈനാമിക് സൈഡ് പാനൽ സീ സർഫേസ് ടെമ്പറേച്ചർ (SST), സീ സർഫേസ് സാലിനിറ്റി (SSS), സീ സർഫേസ് ഹൈറ്റ് (SSH), കിഴക്കോട്ട്/വടക്കോട്ട് കറന്റ് വെലോസിറ്റികൾ (UO, VO) എന്നിവ ഉൾപ്പെടുന്ന തത്സമയ ഉപരിതല പാരാമീറ്ററുകൾ പ്രദർശിപ്പിക്കുന്നു, ഒപ്പം ഒരു ഇന്ററാക്ടീവ് ആഴം തിരിച്ചുള്ള ലംബ താപനില പ്രൊഫൈൽ ഗ്രാഫും നൽകുന്നു.",
    step4Title: "4. റീജിയണൽ ലെയർ മോഡുകളും വിഷ്വലൈസേഷനും",
    step4Desc: "കോർഡിനേറ്റ് ഫീൽഡുകൾ ശൂന്യമായി വിട്ടുകൊണ്ട് ഒരു നിർദ്ദിഷ്ട ആഴത്തിലുള്ള മൂല്യം തിരഞ്ഞെടുക്കുക, സമഗ്രമായ റീജിയണൽ വിഷ്വലൈസേഷൻ മോഡുകൾ അൺലോക്ക് ചെയ്യുക: സ്വതന്ത്ര ARGO നിരീക്ഷണ ഗ്രൗണ്ട് ട്രൂത്ത് മാപ്പുകൾ, കൺവ്‍ഫോർമർ ഡീപ്-ലേണിംഗ് പ്രവചനങ്ങൾ, സമ്പൂർണ്ണ സ്പേഷ്യൽ പിശക് മാപ്പിംഗ്.",
    aboutTitle: "രചയിതാക്കളെയും കോർ ടീമിനെയും കുറിച്ച്",
